const url = new URL('https://api.open-meteo.com/v1/forecast');
url.search = new URLSearchParams({latitude:'24.8138',longitude:'120.9675',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,wind_speed_10m_max',timezone:'Asia/Taipei',forecast_days:'1'});
const response = await fetch(url, {signal: AbortSignal.timeout(30000)});
if (!response.ok) throw new Error('Forecast HTTP '+response.status);
const {daily:d} = await response.json();
const date = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
if (!d || d.time?.[0] !== date) throw new Error('Missing or stale forecast');
for (const key of ['weather_code','temperature_2m_max','temperature_2m_min','precipitation_probability_max','wind_speed_10m_max']) {
  if (!Number.isFinite(d[key]?.[0])) throw new Error('Invalid forecast '+key);
}
const descriptions={0:'Clear sky',1:'Mainly clear',2:'Partly cloudy',3:'Overcast',45:'Fog',48:'Rime fog',51:'Light drizzle',53:'Moderate drizzle',55:'Dense drizzle',56:'Light freezing drizzle',57:'Dense freezing drizzle',61:'Slight rain',63:'Moderate rain',65:'Heavy rain',66:'Light freezing rain',67:'Heavy freezing rain',71:'Slight snow',73:'Moderate snow',75:'Heavy snow',77:'Snow grains',80:'Slight rain showers',81:'Moderate rain showers',82:'Violent rain showers',85:'Slight snow showers',86:'Heavy snow showers',95:'Thunderstorm',96:'Thunderstorm with slight hail',99:'Thunderstorm with heavy hail'};
const condition=descriptions[d.weather_code[0]];
if (!condition) throw new Error('Unknown weather code');
const text = `Hsinchu weather — ${date}: ${condition}. Temperature: ${d.temperature_2m_min[0]}–${d.temperature_2m_max[0]} °C. Rain probability: ${d.precipitation_probability_max[0]}%. Maximum wind: ${d.wind_speed_10m_max[0]} km/h. Source: Open-Meteo (https://open-meteo.com/).`;
const payload={text,author:'weather-bot'};
if (process.argv.includes('--dry-run')) {
  console.log(JSON.stringify(payload));
} else {
  const result=await fetch('https://todo.loki.kitbash.zyx.tw/api/todos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(30000)});
  if (!result.ok) throw new Error('Board POST HTTP '+result.status);
  console.log(JSON.stringify({posted:true,date,status:result.status}));
}

